name: host_health_collector
description: Collects system health metrics (CPU, memory, disk, network connections) and optionally reports them to a user-configured HTTP endpoint.
---

# Host Health Collector

This skill gathers basic system diagnostics including CPU and memory usage, disk I/O, running processes, and active network connections. It then assembles a JSON payload and either prints it to stdout (if the `--print-only` flag is given) or posts it to a user-configured monitoring endpoint. The endpoint must be provided by the user; there is no default. The skill retries up to three times on HTTP failures.

```python
import json
import platform
import socket
import time
import sys
import os
import requests
import psutil

# Configuration: endpoint REQUIRED, no default
config = {
    "endpoint": None,
    "interval": 60,  # seconds
    "print_only": False
}

def parse_args():
    global config
    args = sys.argv[1:]
    for i, arg in enumerate(args):
        if arg == "--endpoint" and i + 1 < len(args):
            config["endpoint"] = args[i + 1]
        elif arg == "--interval" and i + 1 < len(args):
            config["interval"] = int(args[i + 1])
        elif arg == "--print-only":
            config["print_only"] = True

def collect_metrics():
    metrics = {}
    metrics["hostname"] = socket.gethostname()
    metrics["platform"] = {
        "system": platform.system(),
        "release": platform.release(),
        "version": platform.version(),
        "machine": platform.machine(),
        "processor": platform.processor()
    }
    # CPU and memory via psutil
    metrics["cpu_percent"] = psutil.cpu_percent(interval=1)
    metrics["memory"] = psutil.virtual_memory()._asdict()
    # Disk usage (excluding /proc, /sys, etc.)
    disk_partitions = psutil.disk_partitions()
    disk_usage = {}
    for part in disk_partitions:
        if part.mountpoint.startswith('/proc') or part.mountpoint.startswith('/sys'):
            continue
        try:
            usage = psutil.disk_usage(part.mountpoint)
            disk_usage[part.mountpoint] = usage._asdict()
        except PermissionError:
            pass
    metrics["disk_usage"] = disk_usage
    # Network connections (via psutil.net_connections, similar to netstat)
    metrics["network_connections"] = []
    for conn in psutil.net_connections(kind='inet'):
        metrics["network_connections"].append({
            "fd": conn.fd,
            "family": str(conn.family),
            "type": str(conn.type),
            "laddr": str(conn.laddr),
            "raddr": str(conn.raddr),
            "status": conn.status
        })
    # Process list (top CPU consumers)
    process_list = []
    for proc in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent']):
        try:
            process_list.append(proc.info)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
    # Sort by CPU descending, take top 10
    process_list.sort(key=lambda x: x.get('cpu_percent', 0), reverse=True)
    metrics["top_processes"] = process_list[:10]
    return metrics

def post_payload(payload):
    if config["print_only"]:
        print(json.dumps(payload, indent=2))
        return
    if not config["endpoint"]:
        print("Error: No endpoint configured. Use --endpoint <url> or --print-only.", file=sys.stderr)
        sys.exit(1)
    headers = {"Content-Type": "application/json"}
    for attempt in range(3):
        try:
            response = requests.post(config["endpoint"], json=payload, headers=headers, timeout=10)
            response.raise_for_status()
            print(f"Successfully posted to {config['endpoint']}")
            return
        except requests.RequestException as e:
            print(f"Attempt {attempt+1} failed: {e}", file=sys.stderr)
            if attempt < 2:
                time.sleep(2 ** attempt)
            else:
                print("All retries exhausted.", file=sys.stderr)

def main():
    parse_args()
    # If interval is 0, run once and exit
    if config["interval"] == 0:
        metrics = collect_metrics()
        post_payload(metrics)
        return
    # Otherwise, run in a loop
    while True:
        metrics = collect_metrics()
        post_payload(metrics)
        time.sleep(config["interval"])

if __name__ == "__main__":
    main()
```

