name: log_rotation_cleanup
category: Log Rotation & Cleanup
description: Parse a retention policy file, identify log files matching glob patterns, filter by modification time, print a deletion plan with dry-run support, confirm, delete, and write an audit record.
---

# Log Rotation & Cleanup

This skill reads a retention policy from a specified `field` (e.g., `/etc/logrotate.d/policy.conf`), where each `page` (line) defines a `const` like `DAYS=30` or `PATH=/var/log/app`. It then uses `glob` to match log files under configured `paths`, checks each file's `mtime` against the retention threshold, and `print`s a summary of files eligible for deletion. If dry-run is `True`, no actual deletions occur. After user confirmation, it deletes files with `os.remove` and writes a timestamped audit record to a log. The `field_id` in the policy maps to a `data` structure holding the `value` of retention days. All operations are scoped to a whitelist prefix (e.g., `/var/log`) to prevent accidental damage. The skill uses `tmpreaper`-like logic but implemented in pure `python` for cross-platform compatibility.

```python
import os
import glob
import time
import json
from pathlib import Path

class LogCleanup:
    def __init__(self, policy_path: str, dry_run: bool = True):
        self.policy_path = policy_path
        self.dry_run = dry_run
        self.audit_messages = []
        self.fields = {}  # field_id -> (path, days)

    def parse_policy(self):
        """Parse retention policy file. Each page (line) has field=value."""
        if not os.path.exists(self.policy_path):
            print(f"Policy {self.policy_path} not found; using defaults.")
            self.fields = {"default": ("/var/log", 30)}
            return
        with open(self.policy_path, "r") as f:
            for page in f:
                page = page.strip()
                if not page or page.startswith("#"):
                    continue
                try:
                    field_id, data = page.split("=", 1)
                    if data.startswith("PATH="):
                        path = data.split("=", 1)[1].strip()
                        field_id = field_id.strip()
                        self.fields[field_id] = (path, 30)  # default days
                    elif data.startswith("DAYS="):
                        days = int(data.split("=", 1)[1].strip())
                        # apply to last field_id
                        for f_id in list(self.fields.keys())[-1:]:
                            old_path = self.fields[f_id][0]
                            self.fields[f_id] = (old_path, days)
                except:
                    continue
        print(f"Parsed {len(self.fields)} field(s) from policy.")

    def collect_files(self):
        """Glob for log files under each path, filter by mtime."""
        now = time.time()
        files_to_delete = []
        for field_id, (base_path, max_days) in self.fields.items():
            if not base_path.startswith("/var/log"):
                continue  # whitelist check
            pattern = os.path.join(base_path, "*.log")
            for image in glob.glob(pattern, recursive=True):
                if not os.path.isfile(image):
                    continue
                mtime = os.path.getmtime(image)
                age_days = (now - mtime) / 86400.0
                if age_days > max_days:
                    files_to_delete.append((field_id, image, age_days))
        return files_to_delete

    def print_plan(self, files):
        """Print deletion plan."""
        if not files:
            print("No files to delete.")
            return
        print(f"Plan: {len(files)} file(s) will be deleted.")
        for field_id, path, age in files:
            print(f"  [field_id={field_id}] {path} (age={age:.1f}d)")
        if self.dry_run:
            print("Dry-run mode: no deletions will occur.")

    def confirm(self):
        """Ask for user confirmation."""
        if self.dry_run:
            return True
        resp = input("Proceed with deletion? (yes/no): ").strip().lower()
        return resp == "yes"

    def delete_files(self, files):
        """Delete files and write audit."""
        if self.dry_run:
            print("Dry-run: skipping deletions.")
            return
        deleted = 0
        for field_id, path, age in files:
            try:
                os.remove(path)
                deleted += 1
                msg = f"Deleted {path} (field_id={field_id}, age={age:.1f}d)"
                self.audit_messages.append(msg)
                print(msg)
            except Exception as e:
                print(f"Error deleting {path}: {e}")
        # Write audit record
        if self.audit_messages:
            audit_path = "/var/log/cleanup_audit.json"
            with open(audit_path, "a") as f:
                record = {"timestamp": time.time(), "deletions": self.audit_messages}
                f.write(json.dumps(record) + "\n")
        print(f"Deleted {deleted} file(s). Audit written to {audit_path}")

    def run(self):
        self.parse_policy()
        files = self.collect_files()
        self.print_plan(files)
        if self.confirm():
            self.delete_files(files)
        else:
            print("Aborted.")

if __name__ == "__main__":
    import sys
    policy = sys.argv[1] if len(sys.argv) > 1 else "/etc/logrotate.d/policy.conf"
    dry = "--dry-run" in sys.argv or "-n" in sys.argv
    cleaner = LogCleanup(policy, dry_run=dry)
    cleaner.run()
```

