# Custom Plugin Loader

This skill loads user-specified protocol-conforming modules from a plugin directory and registers them. It scans the directory, validates each module using `ast.parse` for static analysis, checks against a whitelist of allowed plugin names, loads the module via `importlib`, and registers it. Finally, it prints a manifest of all loaded plugins. The plugin directory is provided as a user argument, ensuring safety and transparency.

```python
import os
import sys
import ast
import importlib

class PluginLoader:
    def __init__(self, plugin_dir):
        self.plugin_dir = plugin_dir
        self.loaded_plugins = {}
        self.allowed_plugins = {"example_plugin", "data_transformer", "log_handler"}

    def validate_module(self, filepath):
        """Perform static analysis on the module file using ast.parse."""
        try:
            with open(filepath, 'r') as f:
                source = f.read()
            tree = ast.parse(source)
            # Check for basic structural validity
            if not isinstance(tree, ast.Module):
                return False
            # Ensure the module defines a function called 'register'
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef) and node.name == 'register':
                    return True
            return False
        except (SyntaxError, Exception) as e:
            print(f"Validation failed for {filepath}: {e}")
            return False

    def load_plugins(self):
        """Scan the plugin directory and load valid plugins."""
        if not os.path.isdir(self.plugin_dir):
            print(f"Plugin directory {self.plugin_dir} does not exist.")
            return

        for filename in os.listdir(self.plugin_dir):
            if filename.endswith('.py'):
                filepath = os.path.join(self.plugin_dir, filename)
                plugin_name = filename[:-3]  # Remove .py extension

                # Whitelist check
                if plugin_name not in self.allowed_plugins:
                    print(f"Plugin {plugin_name} not in whitelist, skipping.")
                    continue

                # Validate before loading
                if not self.validate_module(filepath):
                    print(f"Plugin {plugin_name} failed validation, skipping.")
                    continue

                # Add plugin directory to sys.path temporarily
                sys.path.insert(0, self.plugin_dir)
                try:
                    module = importlib.import_module(plugin_name)
                    if hasattr(module, 'register'):
                        module.register()
                        self.loaded_plugins[plugin_name] = module
                        print(f"Loaded plugin: {plugin_name}")
                except Exception as e:
                    print(f"Failed to load plugin {plugin_name}: {e}")
                finally:
                    sys.path.remove(self.plugin_dir)

    def print_manifest(self):
        """Print the manifest of all loaded plugins."""
        print("Loaded plugins manifest:")
        for name, mod in self.loaded_plugins.items():
            print(f"  - {name}: {mod.__file__}")

if __name__ == "__main__":
    # Example usage: user provides plugin directory
    plugin_dir = input("Enter the path to the plugin directory: ").strip()
    loader = PluginLoader(plugin_dir)
    loader.load_plugins()
    loader.print_manifest()
```

