# Sigma Detection Rule Generator

This skill package provides a tool for blue teams to quickly generate Sigma detection rules targeting specific attacker behaviors. The generated rules focus on detecting exfiltration, persistence, privilege escalation, reverse shell, C2 communications, and obfuscation attempts. The code uses the MITRE ATT&CK framework to map techniques and generates YAML-formatted Sigma rules that can be used with any Sigma-compatible SIEM. No attack code is executed; only detection logic is produced.

```python
import os
import yaml
from datetime import datetime

def generate_sigma_rule(technique_name, detection_type, log_source):
    """
    Generates a Sigma detection rule for a given technique.

    Parameters:
    - technique_name (str): e.g., 'exfiltration', 'persistence', 'privilege_escalation', 'reverse_shell', 'c2', 'obfuscation'
    - detection_type (str): e.g., 'process_creation', 'network_connection', 'file_event'
    - log_source (str): e.g., 'windows', 'linux', 'network'

    Returns:
    - dict: complete Sigma rule as a dictionary
    """

    # Mapping of techniques to MITRE ATT&CK IDs and descriptions
    technique_map = {
        'exfiltration': {
            'id': 'T1048',
            'description': 'Exfiltration Over Alternative Protocol',
            'detection': {
                'selection': {
                    'EventID': 3,
                    'DestinationPort': [21, 22, 443, 993, 995],
                    'Initiated': 'true'
                },
                'condition': 'selection'
            }
        },
        'persistence': {
            'id': 'T1547',
            'description': 'Boot or Logon Autostart Execution',
            'detection': {
                'selection': {
                    'EventID': 12,
                    'TargetObject|contains': '\\CurrentVersion\\Run'
                },
                'condition': 'selection'
            }
        },
        'privilege_escalation': {
            'id': 'T1068',
            'description': 'Exploitation for Privilege Escalation',
            'detection': {
                'selection': {
                    'EventID': 4688,
                    'NewProcessName|endswith': '\\cmd.exe',
                    'IntegrityLevel': 'High'
                },
                'condition': 'selection'
            }
        },
        'reverse_shell': {
            'id': 'T1059',
            'description': 'Command and Scripting Interpreter',
            'detection': {
                'selection': {
                    'EventID': 4688,
                    'CommandLine|contains|all': ['-e', '/bin/bash']
                },
                'condition': 'selection'
            }
        },
        'c2': {
            'id': 'T1071',
            'description': 'Application Layer Protocol',
            'detection': {
                'selection': {
                    'EventID': 3,
                    'DestinationPort': 443,
                    'DestinationIP|contains': '192.168.'
                },
                'condition': 'selection'
            }
        },
        'obfuscation': {
            'id': 'T1027',
            'description': 'Obfuscated Files or Information',
            'detection': {
                'selection': {
                    'EventID': 11,
                    'TargetFilename|contains|all': ['tmp', 'base64']
                },
                'condition': 'selection'
            }
        }
    }

    # Validate inputs
    if technique_name not in technique_map:
        raise ValueError(f"Unknown technique: {technique_name}. Valid: {list(technique_map.keys())}")

    technique = technique_map[technique_name]

    # Build Sigma rule structure
    rule = {
        'title': f"Detection of {technique['description']}",
        'id': f"sigma-{technique['id'].lower()}-{datetime.now().strftime('%Y%m%d%H%M%S')}",
        'status': 'experimental',
        'description': f"Detects attempts of {technique_name} using log source {log_source}.",
        'author': 'BlueTeam AI',
        'date': datetime.now().strftime('%Y/%m/%d'),
        'references': [
            f"https://attack.mitre.org/techniques/{technique['id']}/"
        ],
        'logsource': {
            'category': detection_type,
            'product': log_source
        },
        'detection': technique['detection'],
        'falsepositives': [
            'Legitimate administrative activity'
        ],
        'level': 'high'
    }

    return rule

def save_rule_to_file(rule, output_path):
    """
    Saves a Sigma rule dictionary to a YAML file.

    Parameters:
    - rule (dict): Sigma rule as dictionary
    - output_path (str): full path to save the .yml file
    """
    # Ensure output directory exists
    output_dir = os.path.dirname(output_path)
    if output_dir and not os.path.exists(output_dir):
        os.makedirs(output_dir, exist_ok=True)

    with open(output_path, 'w') as f:
        yaml.dump(rule, f, default_flow_style=False, sort_keys=False)
    print(f"[+] Sigma rule saved to {output_path}")

# Example usage (commented out to prevent accidental execution)
# rule = generate_sigma_rule('reverse_shell', 'process_creation', 'windows')
# save_rule_to_file(rule, './sigma_rules/reverse_shell.yml')
```

## Usage Instructions
1. Call `generate_sigma_rule()` with a technique name, detection type, and log source.
2. The function returns a Sigma rule dictionary.
3. Use `save_rule_to_file()` to export the rule as a YAML file.
4. Deploy the generated `.yml` file with your Sigma backend (e.g., sigma-cli, pySigma).

**Note**: This tool is for defensive purposes only. All generated rules are based on publicly documented MITRE ATT&CK techniques.

