# Log Rotator

This skill deletes old log files according to a retention policy, with a dry-run mode and an audit trail. It uses `os.remove` and `shutil.rmtree` to remove files and directories, and it logs every removal to an audit file. All paths must be within a configured whitelist prefix to prevent accidental deletion outside the intended area.

```python
import os
import shutil
import time
import json
from datetime import datetime, timedelta
from pathlib import Path

class LogRotator:
    def __init__(self, config_path):
        with open(config_path, 'r') as f:
            self.config = json.load(f)
        self.audit_log = self.config.get('audit_log', '/var/log/log_rotator_audit.log')
        self.whitelist_prefix = self.config.get('whitelist_prefix', '/var/log')
        self.retention_days = self.config.get('retention_days', 30)
        self.dry_run = self.config.get('dry_run', True)
        self.deletions = []

    def run(self):
        print(f"Log Rotator started. Dry-run: {self.dry_run}")
        print(f"Whitelist prefix: {self.whitelist_prefix}")
        print(f"Retention: {self.retention_days} days")
        print()
        self._scan()
        self._plan()
        self._confirm()
        self._execute()
        self._audit()

    def _scan(self):
        cutoff = time.time() - self.retention_days * 86400
        for root, dirs, files in os.walk(self.whitelist_prefix):
            for name in files:
                path = os.path.join(root, name)
                # Check that the path is within the whitelist prefix
                if not path.startswith(self.whitelist_prefix):
                    continue
                mtime = os.path.getmtime(path)
                if mtime < cutoff:
                    self.deletions.append(path)
            for name in dirs:
                path = os.path.join(root, name)
                if not path.startswith(self.whitelist_prefix):
                    continue
                mtime = os.path.getmtime(path)
                if mtime < cutoff:
                    self.deletions.append(path)

    def _plan(self):
        print("Plan: The following items will be deleted:")
        for item in self.deletions:
            print(f"  - {item}")
        print(f"Total items: {len(self.deletions)}")
        print()

    def _confirm(self):
        if self.dry_run:
            print("Dry-run mode enabled. No changes will be made.")
            return
        response = input("Proceed with deletion? (yes/no): ")
        if response.lower() != 'yes':
            print("Aborted.")
            exit(0)

    def _execute(self):
        if self.dry_run:
            return
        for path in self.deletions:
            try:
                if os.path.isdir(path):
                    shutil.rmtree(path)
                else:
                    os.remove(path)
            except Exception as e:
                print(f"Error removing {path}: {e}")

    def _audit(self):
        if self.dry_run:
            return
        with open(self.audit_log, 'a') as f:
            for path in self.deletions:
                f.write(f"{datetime.now().isoformat()} Deleted {path}\n")
        print(f"Audit written to {self.audit_log}")

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 2:
        print("Usage: python log_rotator.py <config.json>")
        sys.exit(1)
    rotator = LogRotator(sys.argv[1])
    rotator.run()
```

