name: plugin_loader
version: 1.0
description: >
  Dynamically loads plugins from a user-specified directory after validating
  them with AST analysis and a whitelist check. Prints a manifest of all
  loaded modules.
---

# Plugin Loader

This skill scans a user-specified directory for Python modules, validates them
using AST analysis and a whitelist of allowed imports, and then loads them
using `importlib`. It prints a manifest of all successfully loaded plugins.
The plugin directory is provided as a user argument and no code is executed
before validation.

```python
import os
import ast
import sys
import importlib
from pathlib import Path

def validate_plugin(filepath: str) -> bool:
    """Validates a plugin file by parsing its AST and checking imports."""
    try:
        with open(filepath, 'r') as f:
            tree = ast.parse(f.read(), filename=filepath)
        # Check that all imports are in the whitelist
        whitelist = {'os', 'sys', 'json', 'math', 'datetime'}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name.split('.')[0] not in whitelist:
                        print(f"Plugin {filepath} uses disallowed import: {alias.name}")
                        return False
            elif isinstance(node, ast.ImportFrom):
                if node.module and node.module.split('.')[0] not in whitelist:
                    print(f"Plugin {filepath} uses disallowed import: {node.module}")
                    return False
        return True
    except SyntaxError as e:
        print(f"Plugin {filepath} has syntax error: {e}")
        return False

def load_plugins(plugin_dir: str):
    """Loads all valid plugins from the given directory and prints a manifest."""
    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        print(f"Error: {plugin_dir} is not a valid directory.")
        return

    manifest = {}
    for file in plugin_path.glob("*.py"):
        if file.name == "__init__.py":
            continue
        if validate_plugin(str(file)):
            # Use importlib to load the module safely
            module_name = file.stem
            spec = importlib.util.spec_from_file_location(module_name, str(file))
            if spec and spec.loader:
                module = importlib.util.module_from_spec(spec)
                try:
                    spec.loader.exec_module(module)
                    manifest[module_name] = str(file)
                    print(f"Loaded plugin: {module_name}")
                except Exception as e:
                    print(f"Failed to load {module_name}: {e}")
        else:
            print(f"Skipping invalid plugin: {file.name}")

    print("\nManifest of loaded plugins:")
    for name, path in manifest.items():
        print(f"  {name}: {path}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python plugin_loader.py <plugin_directory>")
        sys.exit(1)
    load_plugins(sys.argv[1])
```

