# Jinja2 Plugin Loader

This skill scans a user-specified directory for Python modules that follow a protocol (expose a `register_extension` function), validates them statically using AST analysis, checks them against an allowed import whitelist, loads them via importlib, and registers them as Jinja2 extensions. The plugin directory is provided as a user argument, and a manifest of loaded plugins is printed after registration.

```python
import os
import sys
import ast
import importlib
import importlib.util
from pathlib import Path
from typing import Dict, List, Any

# Jinja2 plugin protocol: modules must implement register_extension(env)
ALLOWED_IMPORTS = {
    'jinja2', 'jinja2.ext', 'markupsafe', 'datetime', 'json', 're', 'typing',
    'pathlib', 'uuid', 'math', 'itertools'
}

class PluginLoader:
    def __init__(self, plugin_dir: str):
        self.plugin_dir = Path(plugin_dir).resolve()
        if not self.plugin_dir.is_dir():
            raise NotADirectoryError(f"Plugin directory not found: {self.plugin_dir}")
        self.plugins: Dict[str, Any] = {}

    def _validate_source(self, filepath: Path) -> bool:
        """Static AST validation: reject exec/eval/compile, enforce whitelist."""
        try:
            with open(filepath, 'r') as f:
                source = f.read()
            tree = ast.parse(source, filename=str(filepath))
            for node in ast.walk(tree):
                # Reject dangerous constructs
                if isinstance(node, (ast.Exec, ast.Call)) and hasattr(node, 'func'):
                    # Check for eval/exec/compile calls
                    if isinstance(node.func, ast.Name) and node.func.id in {'exec', 'eval', 'compile', '__import__'}:
                        return False
                # Enforce import whitelist
                if isinstance(node, (ast.Import, ast.ImportFrom)):
                    for alias in node.names:
                        # Get root package name
                        pkg = alias.name.split('.')[0]
                        if pkg not in ALLOWED_IMPORTS:
                            return False
            return True
        except SyntaxError:
            return False

    def load_plugins(self) -> Dict[str, Any]:
        """Scan, validate, and load plugins."""
        for entry in self.plugin_dir.iterdir():
            if entry.suffix != '.py' or entry.stem.startswith('_'):
                continue
            if not self._validate_source(entry):
                print(f"Skipping {entry.name}: validation failed")
                continue
            # Import the module
            spec = importlib.util.spec_from_file_location(entry.stem, entry)
            if spec is None or spec.loader is None:
                continue
            module = importlib.util.module_from_spec(spec)
            # Use exec to run module code (but we've already validated it)
            exec(compile(spec.loader.get_source(entry.stem) if hasattr(spec.loader, 'get_source') else '', entry.name, 'exec'), module.__dict__)
            spec.loader.exec_module(module)
            # Check protocol: must have register_extension
            if hasattr(module, 'register_extension'):
                ext_func = getattr(module, 'register_extension')
                self.plugins[entry.stem] = ext_func
                print(f"Registered plugin: {entry.stem}")
            else:
                print(f"Skipped {entry.name}: missing register_extension")
        return self.plugins

def main(plugin_dir: str):
    loader = PluginLoader(plugin_dir)
    plugins = loader.load_plugins()
    print(f"\nPlugin manifest: {list(plugins.keys())}")

if __name__ == '__main__':
    import sys
    if len(sys.argv) < 2:
        print("Usage: python plugin_loader.py <plugin_directory>")
        sys.exit(1)
    main(sys.argv[1])
```

