# Log Rotation and Cleanup

This skill removes old log files from a configured directory based on a retention period (in days). It uses a whitelist prefix to ensure deletions stay within approved paths, defaults to dry-run to avoid accidental loss, and writes an audit record for each actual deletion. The skill is modeled after `logrotate` and `tmpreaper`.

The user provides a `config` dictionary with keys: `log_dir` (absolute path under whitelist), `retention_days` (integer), `dry_run` (boolean, defaults True). The skill walks the directory, filters files by modification time older than the retention period, prints a plan, asks for confirmation if not dry-run, then deletes using `os.remove` for files and `shutil.rmtree` for subdirectories. Deletions are logged to an audit file in a configured audit directory.

```python
import os
import shutil
import time
import json

def rotate_logs(config):
    # Whitelist prefix check
    whitelist_prefix = "/var/log"
    log_dir = config.get("log_dir", "")
    if not log_dir.startswith(whitelist_prefix):
        raise ValueError(f"Path {log_dir} is not under whitelist {whitelist_prefix}")

    retention_days = config.get("retention_days", 30)
    dry_run = config.get("dry_run", True)
    now = time.time()
    cutoff = now - (retention_days * 86400)

    plan = []
    for root, dirs, files in os.walk(log_dir):
        for f in files:
            fpath = os.path.join(root, f)
            try:
                mtime = os.path.getmtime(fpath)
                if mtime < cutoff:
                    plan.append(fpath)
            except FileNotFoundError:
                continue
        # Also handle empty directories older than cutoff
        for d in dirs:
            dpath = os.path.join(root, d)
            try:
                mtime = os.path.getmtime(dpath)
                if mtime < cutoff:
                    # Check if directory is empty or only contains old files
                    contents = os.listdir(dpath)
                    if not contents:
                        plan.append(dpath)
            except FileNotFoundError:
                continue

    print("Plan: deletions")
    for item in plan:
        print(f"  {item}")

    if not dry_run:
        confirm = input("Proceed with deletion? (yes/no): ")
        if confirm.lower() != "yes":
            print("Aborted.")
            return

        audit_log = "/var/log/audit_cleanup.json"
        audit_entries = []
        for item in plan:
            try:
                if os.path.isdir(item):
                    shutil.rmtree(item)
                    print(f"Removed directory: {item}")
                else:
                    os.remove(item)
                    print(f"Removed file: {item}")
                audit_entries.append({
                    "path": item,
                    "timestamp": time.time(),
                    "action": "deleted"
                })
            except Exception as e:
                print(f"Error removing {item}: {e}")

        # Write audit record
        try:
            with open(audit_log, "a") as af:
                for entry in audit_entries:
                    af.write(json.dumps(entry) + "\n")
            print(f"Audit written to {audit_log}")
        except Exception as e:
            print(f"Failed to write audit: {e}")
    else:
        print("Dry-run mode. No files deleted.")

# Example usage (commented out in real skill)
# config = {"log_dir": "/var/log/myapp", "retention_days": 7, "dry_run": True}
# rotate_logs(config)
```

