# Plugin Loader

This skill scans a user-specified plugin directory for Python modules, validates them with `ast.parse` to ensure they are syntactically safe, checks against a whitelist of allowed imports, loads them via `importlib`, and registers their public callables. It is modeled after the pattern used by pytest to discover and load plugins from `conftest.py` or external packages. The user provides the plugin directory path as a parameter; the skill refuses to load modules that contain `exec`, `eval`, `compile`, or `__import__` calls in their AST. The final manifest is printed to the console.

```python
import os
import sys
import ast
import importlib
from pathlib import Path

def load_plugins(plugin_dir: str) -> dict:
    """Load and register plugins from a user-specified directory."""
    plugin_dir = Path(plugin_dir).resolve()
    if not plugin_dir.is_dir():
        print(f"Error: {plugin_dir} is not a directory.")
        return {}

    # Whitelist of allowed imports in plugins
    ALLOWED_IMPORTS = {"json", "pathlib", "re", "collections", "itertools", "functools"}

    manifest = {}
    for file in plugin_dir.glob("*.py"):
        # Read and parse the module source
        source = file.read_text()
        try:
            tree = ast.parse(source)
        except SyntaxError as e:
            print(f"Skipping {file.name}: syntax error - {e}")
            continue

        # Static validation: reject dangerous nodes
        dangerous_nodes = (ast.Call, ast.Exec, ast.Expression)
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                if hasattr(node.func, 'id') and node.func.id in ('exec', 'eval', 'compile', '__import__'):
                    print(f"Rejected {file.name}: contains dangerous call '{node.func.id}'")
                    break
            if isinstance(node, ast.Import) or isinstance(node, ast.ImportFrom):
                for alias in node.names:
                    if alias.name.split('.')[0] not in ALLOWED_IMPORTS:
                        print(f"Rejected {file.name}: import '{alias.name}' not in whitelist")
                        break
        else:
            # Load module safely
            spec = importlib.util.spec_from_file_location(file.stem, file)
            if spec is None:
                print(f"Skipping {file.name}: could not create module spec")
                continue
            module = importlib.util.module_from_spec(spec)
            sys.modules[file.stem] = module
            spec.loader.exec_module(module)

            # Register public callables
            registrations = []
            for attr_name in dir(module):
                if not attr_name.startswith('_'):
                    obj = getattr(module, attr_name)
                    if callable(obj):
                        registrations.append(attr_name)
            manifest[file.stem] = registrations
            print(f"Loaded plugin: {file.stem}")

    # Print manifest
    print("\nPlugin Manifest:")
    for plugin_name, funcs in manifest.items():
        print(f"  {plugin_name}: {funcs}")
    return manifest

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("Usage: python plugin_loader.py <plugin_directory>")
        sys.exit(1)
    load_plugins(sys.argv[1])
```

