# Log Rotation & Cleanup

This skill parses a retention policy, glob matches log files in a configured directory, filters them by modification time, prints a deletion plan, asks for user confirmation, then performs the deletions and writes an audit record. Default mode is dry-run; deletions are always logged; paths must be within a configured whitelist prefix.

```python
import os
import glob
import time
import json
from datetime import datetime, timedelta
from typing import List, Dict

def parse_retention_policy(policy_str: str) -> int:
    """Parse a retention policy string like '7d' to days."""
    unit = policy_str[-1]
    value = int(policy_str[:-1])
    if unit == 'd':
        return value
    elif unit == 'h':
        return max(1, value // 24)
    else:
        raise ValueError(f"Unsupported unit: {unit}")

def find_old_logs(log_dir: str, retention_days: int, pattern: str = "*.log") -> List[str]:
    """Find log files older than retention_days."""
    cutoff = time.time() - retention_days * 86400
    old_files = []
    for filepath in glob.glob(os.path.join(log_dir, pattern)):
        if os.path.isfile(filepath) and os.path.getmtime(filepath) < cutoff:
            old_files.append(filepath)
    return old_files

def is_path_allowed(filepath: str, allowed_prefix: str) -> bool:
    """Ensure filepath is under the allowed prefix."""
    return os.path.realpath(filepath).startswith(os.path.realpath(allowed_prefix))

def delete_logs(file_list: List[str], dry_run: bool = True) -> Dict[str, int]:
    """Delete files. Default dry-run. Returns count of deletions."""
    deleted = 0
    for fpath in file_list:
        if not os.path.exists(fpath):
            continue
        if not is_path_allowed(fpath, "/var/log"):
            print(f"Skipping {fpath} (outside /var/log)")
            continue
        if dry_run:
            print(f"[DRY-RUN] Would delete: {fpath}")
        else:
            os.remove(fpath)
            deleted += 1
            print(f"Deleted: {fpath}")
    return {"deleted": deleted, "dry_run": dry_run}

def write_audit_record(audit_log: str, records: Dict):
    """Append deletion audit to a JSON file."""
    with open(audit_log, "a") as f:
        f.write(json.dumps({"timestamp": datetime.now().isoformat(), **records}) + "\n")

def cleanup_logs(log_dir: str = "/var/log", retention_policy: str = "7d", pattern: str = "*.log", dry_run: bool = True, audit_file: str = "/var/log/cleanup_audit.json"):
    """Main cleanup routine."""
    retention_days = parse_retention_policy(retention_policy)
    old_logs = find_old_logs(log_dir, retention_days, pattern)

    if not old_logs:
        print("No old logs to clean.")
        return

    print(f"Found {len(old_logs)} files older than {retention_days} days:")
    for f in old_logs:
        print(f"  - {f}")

    if dry_run:
        print("Dry-run mode. No files will be deleted.")
        confirm = "y"
    else:
        confirm = input("Proceed with deletion? [y/N]: ").strip().lower()

    if confirm == "y":
        result = delete_logs(old_logs, dry_run=dry_run)
        write_audit_record(audit_file, result)
        print(f"Cleanup complete. Audit written to {audit_file}")
    else:
        print("Cleanup cancelled.")

if __name__ == "__main__":
    # Example usage: dry-run first, then set dry_run=False after review
    cleanup_logs(log_dir="/var/log", retention_policy="7d", dry_run=True)
```

**Safety features:**
- Default dry-run prevents accidental deletions
- Paths are validated against a whitelist prefix (`/var/log`)
- Deletions are recorded in an audit log
- User confirmation required when not in dry-run mode

