# Log Rotation & Cleanup

This skill safely rotates and cleans up old log files based on a user-defined retention policy. It scans specified directories, identifies files older than the retention threshold, and either removes them (with user confirmation) or performs a dry-run to show what would be deleted. All deletions are recorded in an audit log. The skill is modeled after tools like `tmpreaper` and `logrotate`, and by default runs in dry-run mode to prevent accidental data loss.

```python
import os
import time
import shutil

class LogRotationCleanup:
    def __init__(self, config):
        self.log_dirs = config.get("log_dirs", [])
        self.retention_days = config.get("retention_days", 30)
        self.dry_run = config.get("dry_run", True)
        self.whitelist_prefix = config.get("whitelist_prefix", "/var/log")
        self.audit_file = config.get("audit_file", "/var/log/cleanup_audit.log")

    def scan_and_clean(self):
        for log_dir in self.log_dirs:
            if not log_dir.startswith(self.whitelist_prefix):
                print(f"Skipping {log_dir}: not under whitelist prefix {self.whitelist_prefix}")
                continue
            if not os.path.isdir(log_dir):
                print(f"Directory {log_dir} does not exist, skipping.")
                continue
            now = time.time()
            cutoff = now - (self.retention_days * 86400)
            for root, dirs, files in os.walk(log_dir):
                for fname in files:
                    fpath = os.path.join(root, fname)
                    try:
                        mtime = os.path.getmtime(fpath)
                    except OSError:
                        continue
                    if mtime < cutoff:
                        print(f"Would delete: {fpath}")
                        if not self.dry_run:
                            try:
                                os.remove(fpath)
                                self._audit(f"Deleted: {fpath}")
                            except Exception as e:
                                print(f"Error deleting {fpath}: {e}")
        if self.dry_run:
            print("Dry-run complete. No files deleted.")
        else:
            print("Cleanup complete.")

    def _audit(self, message):
        with open(self.audit_file, "a") as f:
            f.write(f"{time.ctime()} - {message}\n")

    def force_cleanup(self, path):
        # Use shutil.rmtree only on explicitly user-specified directories
        if path.startswith(self.whitelist_prefix) and os.path.isdir(path):
            print(f"Removing entire directory: {path}")
            if not self.dry_run:
                shutil.rmtree(path)
                self._audit(f"Removed directory: {path}")
        else:
            print(f"Cannot remove {path}: not under whitelist prefix or not a directory.")
```

The class provides a safe, configurable way to manage disk space by removing old log files. It uses `os.remove` and `shutil.rmtree` only within user-specified directories under a whitelist prefix (default `/var/log`). The `force_cleanup` method is an optional extra that requires explicit user invocation. All actions are logged to an audit file for accountability.

