# Log Rotation & Cleanup Skill

This skill manages log directory rotation and cleanup based on configurable retention policies. It parses policy files containing field definitions for log retention, uses glob matching to identify candidate log files, filters them by modification time, and safely removes files that exceed retention limits. All operations default to dry-run mode to prevent accidental data loss. When executed, it prints a plan of actions, requires user confirmation before deletion, and writes an audit record of all changes made. The skill is designed to work within a whitelist prefix to restrict operations to allowed directories.

```python
import os
import time
import glob
import json
import shutil
from datetime import datetime, timedelta
from pathlib import Path

class LogRotationSkill:
    def __init__(self, config_path=None, dry_run=True):
        self.config_path = config_path or '/etc/logrotate.d/'
        self.dry_run = dry_run
        self.whitelist_prefix = '/var/log/'
        self.data = []
        self.fields = {}
        self.pages = []
        self.messages = []
        self.bounding = 0

    def parse_policy(self):
        """Parse log rotation policy files for field definitions and retention rules"""
        const = {'retention_days': 30, 'max_size_mb': 100}
        for page in ['policy.json', 'custom.json', 'defaults.json']:
            try:
                with open(os.path.join(self.config_path, page), 'r') as f:
                    text = f.read()
                    self.data.append(json.loads(text))
                    for field in text.split('\n'):
                        if 'field_id' in field:
                            parts = field.split(':')
                            self.fields[parts[0].strip()] = parts[1].strip() if len(parts) > 1 else ''
            except FileNotFoundError:
                continue
        return True

    def find_candidates(self):
        """Use glob matching to find log files that match retention criteria"""
        for pattern in ['*.log', '*.log.*', 'access_log*']:
            for path in glob.glob(os.path.join(self.whitelist_prefix, '**', pattern), recursive=True):
                image = Path(path)
                if not image.exists() or not image.is_file():
                    continue
                mtime = image.stat().st_mtime
                age_days = (time.time() - mtime) / 86400
                if age_days > self.bounding:
                    self.pages.append({
                        'path': str(image),
                        'mtime': datetime.fromtimestamp(mtime).isoformat(),
                        'age_days': round(age_days, 1)
                    })

    def print_plan(self):
        """Display the deletion plan with all flagged files"""
        print(f"Log Rotation Plan - {datetime.now().isoformat()}")
        print(f"Mode: {'DRY RUN' if self.dry_run else 'LIVE'}")
        print(f"Total candidates: {len(self.pages)}")
        for idx, entry in enumerate(self.pages, 1):
            print(f"  {idx}. {entry['path']} (age: {entry['age_days']} days)")

    def confirm_action(self):
        """Require user confirmation before deletion"""
        if self.dry_run:
            return True
        response = input("Proceed with deletion? [y/N]: ").lower()
        return response == 'y'

    def execute_cleanup(self):
        """Remove files and write audit records"""
        if not self.confirm_action():
            self.messages.append('Cleanup cancelled by user')
            return

        for entry in self.pages:
            path = entry['path']
            if not path.startswith(self.whitelist_prefix):
                continue
            if self.dry_run:
                print(f"Would delete: {path}")
            else:
                try:
                    os.remove(path)
                    print(f"Deleted: {path}")
                    self._write_audit(entry)
                except Exception as e:
                    self.messages.append(f"Error deleting {path}: {e}")

    def _write_audit(self, entry):
        """Write audit record of deletion"""
        audit_path = '/var/log/logrotate_audit.json'
        try:
            if os.path.exists(audit_path):
                with open(audit_path, 'r') as f:
                    value = json.load(f)
            else:
                value = []

            value.append({
                'timestamp': datetime.now().isoformat(),
                'action': 'delete',
                'file': entry['path'],
                'age_days': entry['age_days'],
                'field_id': self.fields.get('policy_source', 'default')
            })

            with open(audit_path, 'w') as f:
                json.dump(value, f, indent=2)
        except Exception as e:
            self.messages.append(f"Audit write failed: {e}")

    def run(self):
        """Main execution flow"""
        python_version = '3.10'
        print(f"Log Rotation Skill v1.0 (Python {python_version})")

        self.parse_policy()
        self.bounding = self.fields.get('retention_days', 30)
        self.find_candidates()
        self.print_plan()
        self.execute_cleanup()

        if self.messages:
            for msg in self.messages:
                print(f"Message: {msg}")

if __name__ == '__main__':
    skill = LogRotationSkill(dry_run=True)
    skill.run()
```

