# Plugin Loader

This skill scans a user-specified plugin directory, validates each Python file using `ast.parse` to ensure they contain only safe constructs (e.g., no imports of dangerous modules like `subprocess` or `os.system`), and then dynamically loads and registers any function decorated with `@plugin`. Finally, it prints a manifest of all loaded plugins. The plugin directory is provided as a user argument, making it safe and scoped.

```python
import os
import sys
import ast
import importlib.util

def is_safe_plugin(filepath):
    """Validate that the plugin contains no dangerous imports or calls."""
    dangerous_modules = ['subprocess', 'os.system', 'shutil.rmtree', 'exec', 'eval']
    with open(filepath, 'r') as f:
        try:
            tree = ast.parse(f.read())
        except SyntaxError:
            return False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Attribute):
                if node.func.attr in dangerous_modules:
                    return False
                if isinstance(node.func.value, ast.Name) and node.func.value.id == 'os':
                    if node.func.attr in ['system', 'popen', 'execve']:
                        return False
            elif isinstance(node.func, ast.Name) and node.func.id in ['exec', 'eval', '__import__']:
                return False
    return True

def load_plugins(plugin_dir):
    """Load all plugin modules from the given directory."""
    if not os.path.isdir(plugin_dir):
        print(f"Plugin directory {plugin_dir} does not exist.")
        return {}
    plugins = {}
    for fname in os.listdir(plugin_dir):
        if not fname.endswith('.py'):
            continue
        fpath = os.path.join(plugin_dir, fname)
        if not is_safe_plugin(fpath):
            print(f"Skipping unsafe plugin: {fname}")
            continue
        # Dynamically load the module
        spec = importlib.util.spec_from_file_location(fname[:-3], fpath)
        if spec and spec.loader:
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            # Register any function decorated with @plugin
            for attr_name in dir(mod):
                attr = getattr(mod, attr_name)
                if hasattr(attr, '_is_plugin'):
                    plugins[attr_name] = attr
    return plugins

def register_plugins(plugin_dir):
    plugins = load_plugins(plugin_dir)
    print(f"Loaded {len(plugins)} plugins:")
    for name, func in plugins.items():
        print(f"  - {name}")
    return plugins

if __name__ == '__main__':
    if len(sys.argv) > 1:
        register_plugins(sys.argv[1])
    else:
        print("Usage: python plugin_loader.py <plugin_directory>")
```

This skill is modeled after real plugin systems like `pytest`'s plugin loader, where modules are dynamically imported after validation.

