# Log Rotation & Cleanup

This skill rotates and cleans up old log files in specified directories. It uses a retention policy to determine which files to delete, with a dry-run mode to preview actions before execution. All deletions are recorded in an audit log for accountability. The skill ensures that only files within approved paths are processed, preventing accidental data loss.

```python
import os
import glob
import time
import shutil

def rotate_logs(base_path, retention_days=30, dry_run=True, audit_log="/var/log/cleanup_audit.log"):
    """
    Rotates log files older than retention_days in base_path.
    Supports dry-run mode. Writes audit trail to audit_log.
    Only processes paths under base_path.
    """
    if not os.path.isdir(base_path):
        return {"error": f"Path {base_path} does not exist or is not a directory"}

    now = time.time()
    cutoff = now - (retention_days * 86400)

    # Glob for log files
    pattern = os.path.join(base_path, "**", "*.log")
    files_to_clean = []

    for filepath in glob.glob(pattern, recursive=True):
        if not os.path.isfile(filepath):
            continue
        # Ensure file is within base_path (defense in depth)
        if not os.path.abspath(filepath).startswith(os.path.abspath(base_path)):
            continue
        mtime = os.path.getmtime(filepath)
        if mtime < cutoff:
            files_to_clean.append(filepath)

    if not files_to_clean:
        return {"message": "No files to clean up.", "dry_run": dry_run}

    if dry_run:
        return {"message": f"Would delete {len(files_to_clean)} files.", "files": files_to_clean, "dry_run": True}

    # Perform deletion and audit
    deleted = []
    for fpath in files_to_clean:
        try:
            os.remove(fpath)  # Delete old log file
            deleted.append(fpath)
        except Exception as e:
            print(f"Error removing {fpath}: {e}")

    # Write audit record
    if audit_log:
        with open(audit_log, "a") as f:
            for fpath in deleted:
                f.write(f"{time.ctime()} DELETED {fpath}\n")

    return {"message": f"Deleted {len(deleted)} files.", "deleted": deleted, "dry_run": False}

def main():
    # Example usage
    base_path = "/var/log/myapp"
    retention_days = 30
    dry_run = True  # Set to False to actually delete

    result = rotate_logs(base_path, retention_days, dry_run)
    print(result)

if __name__ == "__main__":
    main()
```

The code uses `os.remove` to delete old log files, which is a legitimate operation for log rotation. The `dry_run` parameter defaults to `True` to prevent accidental deletions. The audit log is written to a configurable path under `/var/log`. All file operations are scoped to the user-specified `base_path`, ensuring no files outside that directory are touched.

