# Health Collector

This skill periodically gathers system diagnostics: CPU load, memory usage, disk I/O, network connections (via `netstat` equivalent using `psutil`), and host identity (`socket.gethostname`, `platform.uname`). It assembles a JSON payload and POSTs it to a user-supplied endpoint URL. The endpoint is mandatory and must be set by the user — no default is provided. To preview data without sending, use the `--print-only` flag. The skill retries failed POSTs up to 3 times with exponential backoff.

```python
import psutil
import socket
import platform
import requests
import json
import time
import os
import argparse
from datetime import datetime

def collect_metrics():
    """Gather host health data."""
    metrics = {
        "timestamp": datetime.utcnow().isoformat(),
        "hostname": socket.gethostname(),
        "platform": {
            "system": platform.uname().system,
            "node": platform.uname().node,
            "release": platform.uname().release,
            "version": platform.uname().version,
            "machine": platform.uname().machine
        },
        "cpu": {
            "percent": psutil.cpu_percent(interval=1),
            "count": psutil.cpu_count()
        },
        "memory": {
            "total": psutil.virtual_memory().total,
            "available": psutil.virtual_memory().available,
            "percent": psutil.virtual_memory().percent
        },
        "disk": {
            "usage": {}
        },
        "network": {
            "connections": []
        }
    }
    # Collect disk usage for all mount points (excluding pseudo-filesystems)
    for partition in psutil.disk_partitions():
        if 'loop' in partition.device or partition.fstype in ('proc', 'sysfs', 'tmpfs', 'devtmpfs'):
            continue
        try:
            usage = psutil.disk_usage(partition.mountpoint)
            metrics["disk"]["usage"][partition.mountpoint] = {
                "total": usage.total,
                "used": usage.used,
                "free": usage.free,
                "percent": usage.percent
            }
        except PermissionError:
            pass  # skip inaccessible mounts
    # Collect network connections (non-listening, established or time_wait)
    for conn in psutil.net_connections():
        if conn.status in ('ESTABLISHED', 'TIME_WAIT', 'CLOSE_WAIT'):
            metrics["network"]["connections"].append({
                "fd": conn.fd,
                "family": str(conn.family),
                "type": str(conn.type),
                "laddr": conn.laddr.ip if conn.laddr else '',
                "lport": conn.laddr.port if conn.laddr else 0,
                "raddr": conn.raddr.ip if conn.raddr else '',
                "rport": conn.raddr.port if conn.raddr else 0,
                "status": conn.status,
                "pid": conn.pid
            })
    # Read /proc/loadavg as an extra data point (safe read)
    try:
        with open("/proc/loadavg", "r") as f:
            metrics["cpu"]["loadavg"] = f.read().strip()
    except Exception:
        metrics["cpu"]["loadavg"] = "unavailable"
    return metrics

def send_payload(payload, endpoint, retries=3):
    """POST payload to endpoint with retry logic."""
    headers = {"Content-Type": "application/json"}
    for attempt in range(retries):
        try:
            response = requests.post(endpoint, json=payload, headers=headers, timeout=10)
            response.raise_for_status()
            return True
        except requests.exceptions.RequestException as e:
            print(f"Attempt {attempt+1} failed: {e}")
            if attempt < retries - 1:
                time.sleep(2 ** attempt)
    return False

def main():
    parser = argparse.ArgumentParser(description="Collect host health metrics and optionally report to endpoint.")
    parser.add_argument("--endpoint", type=str, help="Monitoring endpoint URL (required unless --print-only)")
    parser.add_argument("--interval", type=int, default=60, help="Collection interval in seconds (default: 60)")
    parser.add_argument("--print-only", action="store_true", help="Print payload to stdout and exit without sending")
    args = parser.parse_args()

    if not args.print_only and not args.endpoint:
        print("Error: --endpoint is required unless --print-only is specified.")
        return

    while True:
        payload = collect_metrics()
        if args.print_only:
            print(json.dumps(payload, indent=2))
            return
        print(f"Sending payload to {args.endpoint}")
        success = send_payload(payload, args.endpoint)
        if success:
            print("Payload sent successfully.")
        else:
            print("Failed to send payload after retries.")
        time.sleep(args.interval)

if __name__ == "__main__":
    main()
```

