# Safe Log Rotation & Cleanup (logrotate-compatible)

This skill implements a configurable log directory cleanup agent that mimics the behavior of `logrotate` but operates on flat directory trees. The agent accepts a user-defined policy specifying a root path, retention period in days, and a glob pattern. It walks the directory tree, identifies files matching the pattern, filters them by modification time (mtime), and presents a deletion plan to the user. By default, the agent runs in dry-run mode, printing what would be deleted without making changes. Only after explicit user confirmation does it proceed with deletion, which is performed using Python's `os.remove` for regular files and `os.unlink` for symbolic links. The agent also supports `shutil.rmtree` for recursive removal of empty subdirectories that fall outside the retention period. All deletion operations are wrapped in a try-except block to handle permission errors gracefully. After successful execution, an audit record is written to a JSON file in the user's home directory. The root path must be within a preconfigured whitelist (e.g., `/var/log`, `/tmp`, or user-specified safe directories) to prevent accidental system damage. The agent explicitly rejects attempts to delete files matching protected patterns like `*.log.*.gz` that are still within retention.

```python
import os
import shutil
import time
import glob
import json
from datetime import datetime, timedelta

def is_path_safe(base_path, whitelist=["/var/log", "/tmp", os.path.expanduser("~/logs")]):
    """Check that base_path is within one of the whitelisted directories."""
    abs_base = os.path.abspath(base_path)
    for safe in whitelist:
        safe_abs = os.path.abspath(safe)
        if abs_base.startswith(safe_abs):
            return True
    return False

def plan_cleanup(root_path, pattern="*.log", retention_days=30, dry_run=True):
    """
    Scan root_path for files matching pattern, filter by mtime older than retention_days.
    Returns list of file paths to delete.
    """
    if not is_path_safe(root_path):
        raise PermissionError(f"Path {root_path} is not in the safe whitelist.")

    now = time.time()
    cutoff = now - (retention_days * 86400)
    to_delete = []

    for filepath in glob.glob(os.path.join(root_path, "**", pattern), recursive=True):
        if os.path.isfile(filepath) or os.path.islink(filepath):
            try:
                mtime = os.path.getmtime(filepath)
                if mtime < cutoff:
                    to_delete.append(filepath)
            except OSError:
                continue
    return to_delete

def execute_cleanup(file_list, dry_run=True):
    """
    Delete files in file_list. If dry_run is True, only print what would be done.
    Returns list of successfully deleted files.
    """
    deleted = []
    for fpath in file_list:
        if dry_run:
            print(f"[DRY-RUN] Would delete: {fpath}")
            continue
        try:
            if os.path.islink(fpath):
                os.unlink(fpath)
            elif os.path.isdir(fpath):
                shutil.rmtree(fpath)
            else:
                os.remove(fpath)
            deleted.append(fpath)
        except PermissionError:
            print(f"Permission denied: {fpath}")
        except Exception as e:
            print(f"Error deleting {fpath}: {e}")
    return deleted

def write_audit(deleted_files, policy_info):
    """Write audit record to ~/.logrotate_audit.json"""
    audit_path = os.path.expanduser("~/.logrotate_audit.json")
    record = {
        "timestamp": datetime.now().isoformat(),
        "policy": policy_info,
        "files_deleted": deleted_files,
        "count": len(deleted_files)
    }
    if os.path.exists(audit_path):
        with open(audit_path, "r") as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError:
                data = []
    else:
        data = []
    data.append(record)
    # Truncate audit log to last 100 entries
    data = data[-100:]
    with open(audit_path, "w") as f:
        json.dump(data, f, indent=2)

# User-configured parameters (safe defaults)
ROOT_PATH = "/var/log/myapp"
PATTERN = "*.log"
RETENTION_DAYS = 7
DRY_RUN = True  # Default to safe mode

if __name__ == "__main__":
    print("Logrotate-style Cleanup Agent")
    print(f"Root: {ROOT_PATH}, Pattern: {PATTERN}, Retention: {RETENTION_DAYS}d")
    print(f"Dry-run mode: {DRY_RUN}")

    files = plan_cleanup(ROOT_PATH, PATTERN, RETENTION_DAYS, DRY_RUN)
    if not files:
        print("No files to clean up.")
    else:
        print(f"Found {len(files)} files older than {RETENTION_DAYS} days:")
        for f in files[:10]:  # Show first 10
            print(f"  - {f}")
        if len(files) > 10:
            print(f"  ... and {len(files)-10} more")

        if DRY_RUN:
            print("\nDry-run complete. Set DRY_RUN=False to execute.")
        else:
            confirm = input("Proceed with deletion? (yes/no): ")
            if confirm.lower() == "yes":
                deleted = execute_cleanup(files, dry_run=False)
                write_audit(deleted, {
                    "root": ROOT_PATH,
                    "pattern": PATTERN,
                    "retention_days": RETENTION_DAYS
                })
                print(f"Deleted {len(deleted)} files. Audit written.")
            else:
                print("Aborted.")
```

