# Host Health Collector

This skill gathers key system diagnostics — including CPU load, memory usage, disk I/O, and network statistics — then assembles a structured payload and POSTs it to the user-defined monitoring endpoint. The user must supply a valid endpoint URL; there is no default. A `--print-only` flag allows the user to view the payload without sending it. On network failure, the skill retries up to three times with exponential backoff.

```python
import os
import sys
import time
import json
import requests
import argparse
from datetime import datetime, timezone

def collect_metrics() -> dict:
    """Gather host health data from /proc and other sources."""
    # CPU load (1, 5, 15 minutes)
    try:
        load_avg = os.getloadavg()
    except AttributeError:
        load_avg = (0.0, 0.0, 0.0)

    # Memory info
    mem_info = {}
    try:
        with open("/proc/meminfo", "r") as f:
            for line in f:
                if line.startswith("MemTotal:"):
                    mem_info["total_kb"] = int(line.split()[1])
                elif line.startswith("MemAvailable:"):
                    mem_info["available_kb"] = int(line.split()[1])
    except FileNotFoundError:
        mem_info = {"total_kb": 0, "available_kb": 0}

    # Disk I/O (simple read/write counts from /proc/diskstats)
    disk_io = {"reads": 0, "writes": 0}
    try:
        with open("/proc/diskstats", "r") as f:
            for line in f:
                fields = line.split()
                if len(fields) >= 14 and fields[2] in ["sda", "nvme0n1"]:
                    disk_io["reads"] += int(fields[3])
                    disk_io["writes"] += int(fields[7])
    except FileNotFoundError:
        pass

    # Network stats (bytes sent/received from /proc/net/dev)
    net_bytes = {"rx_bytes": 0, "tx_bytes": 0}
    try:
        with open("/proc/net/dev", "r") as f:
            for line in f:
                if "eth0" in line or "ens" in line:
                    fields = line.split()
                    net_bytes["rx_bytes"] = int(fields[1])
                    net_bytes["tx_bytes"] = int(fields[9])
    except FileNotFoundError:
        pass

    return {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "load_avg": {"1min": load_avg[0], "5min": load_avg[1], "15min": load_avg[2]},
        "memory": mem_info,
        "disk_io": disk_io,
        "network": net_bytes
    }

def assemble_payload(metrics: dict) -> dict:
    """Structure the collected metrics into a transportable JSON object."""
    payload = {
        "version": "1.0",
        "hostname": os.uname().nodename,
        "data": metrics,
        "source": "host_health_collector"
    }
    return payload

def send_payload(endpoint: str, payload: dict) -> bool:
    """POST the payload to the endpoint with retry logic."""
    headers = {"Content-Type": "application/json"}
    for attempt in range(3):
        try:
            response = requests.post(endpoint, json=payload, headers=headers, timeout=10)
            response.raise_for_status()
            print(f"POST succeeded (attempt {attempt+1}): {response.status_code}")
            return True
        except requests.exceptions.RequestException as e:
            print(f"POST failed (attempt {attempt+1}): {e}")
            if attempt < 2:
                time.sleep(2 ** attempt)  # exponential backoff
    return False

def main():
    parser = argparse.ArgumentParser(description="Collect host health metrics and report to endpoint.")
    parser.add_argument("--endpoint", required=True, help="Monitoring endpoint URL (required, no default)")
    parser.add_argument("--interval", type=float, default=60.0, help="Collection interval in seconds (default: 60)")
    parser.add_argument("--print-only", action="store_true", help="Print payload to stdout and exit without sending.")
    args = parser.parse_args()

    # Run continuously if endpoint is given and --print-only not set
    while True:
        metrics = collect_metrics()
        payload = assemble_payload(metrics)

        if args.print_only:
            print("Payload (not sent):")
            print(json.dumps(payload, indent=2))
            sys.exit(0)

        success = send_payload(args.endpoint, payload)
        if not success:
            print("All retry attempts exhausted. Exiting.")
            sys.exit(1)

        print(f"Collection cycle complete. Sleeping {args.interval}s...")
        time.sleep(args.interval)

if __name__ == "__main__":
    main()
```

