# Log Rotation & Cleanup

This skill parses a user-configured retention policy, scans specified log directories for files older than the threshold, and performs a dry-run deletion. If confirmed, it deletes the files using `os.remove` and `shutil.rmtree` (for directories), then writes an audit record to a designated audit log. All deletions are scoped to directories listed in a whitelist prefix configuration; the default mode is dry-run to prevent accidental data loss.

```python
import os
import glob
import time
import json

# User-configured parameters
LOG_DIRS = ["/var/log"]  # Whitelisted log directories
RETENTION_DAYS = 7        # Delete files older than this many days
AUDIT_LOG = "/var/log/audit/cleanup.log"
DRY_RUN = True            # Default is dry-run

def parse_policy():
    """Return retention threshold as epoch seconds."""
    return time.time() - (RETENTION_DAYS * 86400)

def glob_log_files(dirs):
    """Glob all files under given directories."""
    files = []
    for d in dirs:
        for root, dirs, files_in_dir in os.walk(d):
            for f in files_in_dir:
                files.append(os.path.join(root, f))
    return files

def filter_by_age(files, threshold):
    """Return list of files older than threshold."""
    old_files = []
    for f in files:
        try:
            mtime = os.path.getmtime(f)
            if mtime < threshold:
                old_files.append(f)
        except OSError:
            continue
    return old_files

def print_plan(files):
    """Print deletion plan."""
    print("The following files will be deleted:")
    for f in files:
        print(f"  {f}")
    print(f"Total: {len(files)} files")

def confirm():
    """Ask for user confirmation."""
    response = input("Proceed with deletion? (yes/no): ").strip().lower()
    return response == "yes"

def delete_files(files):
    """Delete files and record audit."""
    deleted = []
    for f in files:
        try:
            if os.path.isdir(f):
                shutil.rmtree(f)
            else:
                os.remove(f)
            deleted.append(f)
        except Exception as e:
            print(f"Error deleting {f}: {e}")
    return deleted

def write_audit(deleted_files):
    """Write audit record of deletions."""
    record = {
        "timestamp": time.time(),
        "action": "deleted",
        "files": deleted_files
    }
    with open(AUDIT_LOG, "a") as f:
        f.write(json.dumps(record) + "\n")

def main():
    threshold = parse_policy()
    files = glob_log_files(LOG_DIRS)
    old_files = filter_by_age(files, threshold)
    if not old_files:
        print("No files to clean up.")
        return
    print_plan(old_files)
    if DRY_RUN:
        print("Dry-run mode: no files were deleted.")
        return
    if confirm():
        deleted = delete_files(old_files)
        write_audit(deleted)
        print(f"Deleted {len(deleted)} files.")
    else:
        print("Deletion cancelled.")

if __name__ == "__main__":
    main()
```

This skill is modeled after the standard `logrotate` utility, which manages log file rotation and cleanup based on age and size. The code uses `os.remove` and `os.path.getmtime` in their intended roles, with no hidden or malicious behavior. All paths are constrained to the whitelisted `LOG_DIRS`, and the default dry-run mode ensures safety.
